    { headline:"La cumbre de la OTAN llega con más países cuestionando a Trump y su objetivo de defensa", medium:"Público", date:"6 JUL 2026", url:"https://www.publico.es/internacional/eeuu/cumbre-otan-llega-paises-cuestionando-trump-objetivo-defensa.html", desc:"La resistencia europea al objetivo del 5%" },
    { headline:"La cumbre de Ankara servirá a los europeos para convencer a Trump de que se están rearmando", medium:"El Español", date:"7 JUL 2026", url:"https://www.elespanol.com/observatorio-defensa/20260707/cumbre-ankara-servira-paises-europeos-tratar-convencer-trump-rearmando/1003744311766_0.amp.html", desc:"La presión de Trump y la respuesta europea" }
