    { headline:"Con el gasto militar entre ceja y ceja: cómo llega Trump a la cumbre de la OTAN", medium:"BioBioChile", date:"6 JUL 2026", url:"https://www.biobiochile.cl/noticias/internacional/eeuu/2026/07/06/con-el-gasto-militar-entre-ceja-y-ceja-como-llega-trump-a-la-cumbre-de-la-otan-en-turquia.shtml", desc:"El contexto de la cumbre y la presión industrial" }
